import{_ as a,H as o,f as i,i as t}from"./chunks/framework.Cvt1eIE0.js";const u=JSON.parse('{"title":"芒伊木 Wiki - 平衡宽幅布局设计方案 (Balanced Wide Wiki)","description":"","frontmatter":{},"headers":[],"relativePath":"docs/superpowers/specs/2026-05-20-balanced-wide-layout-design.md","filePath":"docs/superpowers/specs/2026-05-20-balanced-wide-layout-design.md"}'),d={name:"docs/superpowers/specs/2026-05-20-balanced-wide-layout-design.md"};function r(n,e,l,s,c,h){return o(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="芒伊木-wiki-平衡宽幅布局设计方案-balanced-wide-wiki" tabindex="-1">芒伊木 Wiki - 平衡宽幅布局设计方案 (Balanced Wide Wiki) <a class="header-anchor" href="#芒伊木-wiki-平衡宽幅布局设计方案-balanced-wide-wiki" aria-label="Permalink to &quot;芒伊木 Wiki - 平衡宽幅布局设计方案 (Balanced Wide Wiki)&quot;">​</a></h1><h2 id="_1-目标与背景" tabindex="-1">1. 目标与背景 <a class="header-anchor" href="#_1-目标与背景" aria-label="Permalink to &quot;1. 目标与背景&quot;">​</a></h2><p><strong>目标</strong>：消除正文与右侧大纲（Aside）之间不自然的巨大空白，通过重新分配空间比例，使页面视觉平衡，消除右侧大纲的“孤岛感/小广告感”。 <strong>背景</strong>：之前的修改虽然解决了重叠问题并撑开了布局，但由于正文最大宽度限制较死，导致在高分辨率屏幕下，正文与大纲之间留下了无法利用的空隙。用户希望两者能够更自然地平分或平衡展示空间。</p><h2 id="_2-架构与布局逻辑" tabindex="-1">2. 架构与布局逻辑 <a class="header-anchor" href="#_2-架构与布局逻辑" aria-label="Permalink to &quot;2. 架构与布局逻辑&quot;">​</a></h2><p>放弃硬性的像素宽度对齐，转向基于弹性比例的平衡布局。</p><h3 id="_2-1-整体容器平衡" tabindex="-1">2.1 整体容器平衡 <a class="header-anchor" href="#_2-1-整体容器平衡" aria-label="Permalink to &quot;2.1 整体容器平衡&quot;">​</a></h3><ul><li><strong>容器对齐</strong>：<code>.VPDoc .container</code> 将作为一个整体容器，承载“正文”和“大纲”。</li><li><strong>对齐策略</strong>：在桌面端使用 <code>justify-content: center;</code>，但在两个子板块之间设置合理的 <code>gap</code>（间距），确保它们既不拥挤也不疏离。</li></ul><h3 id="_2-2-右侧大纲-aside-强化" tabindex="-1">2.2 右侧大纲 (Aside) 强化 <a class="header-anchor" href="#_2-2-右侧大纲-aside-强化" aria-label="Permalink to &quot;2.2 右侧大纲 (Aside) 强化&quot;">​</a></h3><ul><li><strong>宽度增加</strong>：将 <code>.aside</code> 和 <code>.aside-container</code> 的固定宽度从 <code>220px</code> 增加到 <code>300px</code>。</li><li><strong>视觉厚度</strong>：增加内部左侧的 <code>padding</code>（如 <code>48px</code>），使大纲内容更靠近视觉中心，同时给左侧留出足够的留白，显得更有“分量”。</li></ul><h3 id="_2-3-正文区-content-area-弹性调整" tabindex="-1">2.3 正文区 (Content Area) 弹性调整 <a class="header-anchor" href="#_2-3-正文区-content-area-弹性调整" aria-label="Permalink to &quot;2.3 正文区 (Content Area) 弹性调整&quot;">​</a></h3><ul><li><strong>宽度上限提升</strong>：设置 <code>.VPDoc .content-container</code> 的最大宽度为 <code>1200px</code>（包含 Infobox 浮动空间）。</li><li><strong>动态填充</strong>：在超宽屏（&gt;1600px）下，适当增加正文与大纲之间的 <code>gap</code>，但确保这个 <code>gap</code> 不超过视觉可接受的范围（如 <code>80px</code>）。</li></ul><h2 id="_3-实现细节-css" tabindex="-1">3. 实现细节 (CSS) <a class="header-anchor" href="#_3-实现细节-css" aria-label="Permalink to &quot;3. 实现细节 (CSS)&quot;">​</a></h2><ul><li>移除之前版本中过度保守的 <code>max-width: 700px</code> 限制。</li><li>确保浮动逻辑（Float &amp; BFC）在更宽的容器下依然有效，不产生重叠。</li><li>优化媒体查询断点，确保在 1280px 到 1920px 之间都有平滑的过渡。</li></ul><h2 id="_4-验证标准" tabindex="-1">4. 验证标准 <a class="header-anchor" href="#_4-验证标准" aria-label="Permalink to &quot;4. 验证标准&quot;">​</a></h2><ol><li><strong>视觉平衡测试</strong>：在 1080p 屏幕下，正文左侧、中间空隙、大纲右侧的比例应接近对称或有节奏的递进，无突兀的大坑。</li><li><strong>Aside 可读性测试</strong>：大纲栏的标题和列表项有充足的横向空间，不发生局促的换行。</li><li><strong>响应式一致性</strong>：在缩放浏览器窗口时，两个板块应同步收缩或位移，不发生突兀的跳变。</li></ol><h2 id="_5-后续规划" tabindex="-1">5. 后续规划 <a class="header-anchor" href="#_5-后续规划" aria-label="Permalink to &quot;5. 后续规划&quot;">​</a></h2><p>为未来可能加入的“多栏数据展示”提供充足的横向空间支持。</p>',17)])])}const _=a(d,[["render",r]]);export{u as __pageData,_ as default};
